def correct_bracketing(brackets: str) -> bool:
    # Validate the input string to ensure it only contains '<' and '>' characters
    if set(brackets) - set(['<', '>']):
        return False

    # Count the number of opening and closing brackets in the input string
    opening_count = brackets.count('<')
    closing_count = brackets.count('>')

    # Check if the number of opening brackets is equal to the number of closing brackets
    if opening_count != closing_count:
        return False

    # Iterate through the input string and check if each opening bracket is matched by a closing bracket
    stack = []
    for bracket in brackets:
        if bracket == '<':
            stack.append(bracket)
        elif bracket == '>':
            if not stack:
                return False
            stack.pop()

    # Return True if all conditions are met, otherwise return False
    return len(stack) == 0

